CREATE TABLE artifacts(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), creator_user_id TEXT NOT NULL, name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 256), mime TEXT NOT NULL CHECK(length(mime) BETWEEN 1 AND 128), size_bytes INTEGER NOT NULL CHECK(size_bytes >= 0), version INTEGER NOT NULL DEFAULT 1 CHECK(version >= 1), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active', 'deleted')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE INDEX artifacts_org ON artifacts(org_id, status, created_at DESC, id DESC);
CREATE TABLE artifact_versions(id TEXT PRIMARY KEY, artifact_id TEXT NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE, version INTEGER NOT NULL CHECK(version >= 1), mime TEXT NOT NULL, size_bytes INTEGER NOT NULL CHECK(size_bytes >= 0), created_at TEXT NOT NULL, UNIQUE(artifact_id, version));
CREATE INDEX artifact_versions_artifact ON artifact_versions(artifact_id, version DESC);
CREATE TABLE artifact_bindings(id TEXT PRIMARY KEY, artifact_id TEXT NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE, org_id TEXT NOT NULL REFERENCES organizations(id), scope TEXT NOT NULL CHECK(scope IN ('execution', 'workspace', 'conversation')), ref_id TEXT NOT NULL CHECK(length(ref_id) BETWEEN 1 AND 128), created_at TEXT NOT NULL, UNIQUE(artifact_id, scope, ref_id));
CREATE INDEX artifact_bindings_lookup ON artifact_bindings(scope, ref_id, org_id);
CREATE TABLE artifact_retention(org_id TEXT PRIMARY KEY REFERENCES organizations(id), max_age_days INTEGER NOT NULL DEFAULT 90 CHECK(max_age_days BETWEEN 1 AND 3650), updated_at TEXT NOT NULL);
